window.OmniFeature=a=>{let target=null,overlay=null,held=false;function close(){overlay?.remove();overlay=null;held=false}function choose(e){const image=e.target.closest?.('img');if(image)target=image}function show(){const focused=document.activeElement;if(focused?.tagName==='IMG')target=focused;if(!target?.isConnected||!target.complete||!target.naturalWidth||overlay)return;const url=target.currentSrc||target.src;let parsed;try{parsed=new URL(url,location.href)}catch(_){return}if(!['https:','http:','blob:','data:'].includes(parsed.protocol))return;overlay=document.createElement('div');overlay.className='ob-image-zoom';overlay.setAttribute('aria-hidden','true');const image=document.createElement('img');image.src=url;image.alt='';image.referrerPolicy='no-referrer';const size=Math.max(50,Math.min(95,Number(a.settings.get('scale'))||85));image.style.maxWidth=size+'vw';image.style.maxHeight=size+'vh';overlay.append(image);document.documentElement.append(overlay)}function down(e){if(a.active&&e.isTrusted&&e.altKey&&e.code==='KeyZ'&&!e.repeat&&!e.target.closest?.('input,textarea,[contenteditable=true]')){e.preventDefault();held=true;show()}}function up(e){if(held&&(e.code==='KeyZ'||e.key==='Alt'))close()}return{enable(){document.addEventListener('pointerover',choose);document.addEventListener('focusin',choose);document.addEventListener('keydown',down,true);document.addEventListener('keyup',up,true);window.addEventListener('blur',close);window.addEventListener('pagehide',close)},disable(){close();target=null;document.removeEventListener('pointerover',choose);document.removeEventListener('focusin',choose);document.removeEventListener('keydown',down,true);document.removeEventListener('keyup',up,true);window.removeEventListener('blur',close);window.removeEventListener('pagehide',close)}}};